2	import { getCollections } from "./collections";
3	import type { Fact } from "./schemas/facts";
4	import { currentlyValidFilter, type FactCategory } from "./schemas/facts";
5	import { FACTS_SEARCH_INDEX_NAME } from "./search";
6	
7	// The read path. Facts are written by extraction, consolidation, contradiction
8	// and review; until now nothing read them back.
9	//
10	// Retrieval is hybrid because German makes it necessary: compound nouns,
11	// internal jargon and product identifiers are exactly what dense embeddings
12	// lose, and on German legal retrieval BM25 beats every dense model outright.
13	// A lexical arm and a semantic arm are fused with reciprocal rank fusion, then
14	// a cross-encoder reranks the survivors.
15	
16	export const FACTS_VECTOR_INDEX_NAME = "facts_vector";
17	
18	/**
19	 * Automated Embedding: Atlas generates the vectors for `text` at index time
20	 * and for the query at search time, so no embedding column is stored on the
21	 * document and no embedding call happens in this process.
22	 *
23	 * `numDimensions` and `model` are immutable once the index exists — changing
24	 * either means rebuilding it. 2048 is voyage-4-large's native width and sits
25	 * above the 1024 floor Atlas recommends for quantized workloads.
26	 */
27	export const factsVectorIndexDefinition = {
28	  fields: [
29	    {
30	      modality: "text",
31	      model: "voyage-4-large",
32	      numDimensions: 2048,
33	      path: "text",
34	      quantization: "scalar",
35	      type: "autoEmbed",
36	    },
37	    // Pre-filters, not post-filters: $vectorSearch returns k nearest
38	    // neighbours and *then* the pipeline continues, so filtering afterwards
39	    // would let another tenant's documents consume this tenant's k.
40	    { path: "tenantId", type: "filter" },
41	    { path: "category", type: "filter" },
42	  ],
43	} as const;
44	
45	/**
46	 * Lexical is weighted at least as heavily as semantic on purpose. German
47	 * compound nouns, ticket ids and product names are where dense retrieval is
48	 * weakest and where the lucene.german analyzer earns its keep.
49	 */
50	export const rankFusionWeights = { lexical: 0.5, semantic: 0.5 } as const;
51	
52	/** Each arm over-fetches relative to the final cut; fusion can only rank
53	 * what the arms surfaced, and the reranker wants headroom too. */
54	const CANDIDATE_MULTIPLIER = 5;
55	const NUM_CANDIDATES_MULTIPLIER = 20;
56	const DEFAULT_LIMIT = 20;
57	
58	export interface HybridFactsSearchOptions {
59	  category?: FactCategory;
60	  includeSuperseded?: boolean;
61	  limit?: number;
62	  query: string;
63	  tenantId: string;
64	}
65	
66	export const buildHybridFactsPipeline = ({
67	  category,
68	  includeSuperseded = false,
69	  limit = DEFAULT_LIMIT,
70	  query,
71	  tenantId,
72	}: HybridFactsSearchOptions): Document[] => {
73	  const perArm = limit * CANDIDATE_MULTIPLIER;
74	  const lifecycle: Document[] = includeSuperseded
75	    ? []
76	    : [{ $match: { ...currentlyValidFilter } }];
77	
78	  const lexicalFilter: Document[] = [
79	    { equals: { path: "tenantId", value: tenantId } },
80	  ];
81	  if (category) {
82	    lexicalFilter.push({ equals: { path: "category", value: category } });
83	  }
84	
85	  const vectorFilter: Document = { tenantId };
86	  if (category) {
87	    vectorFilter.category = category;
88	  }
89	
90	  return [
91	    {
92	      $rankFusion: {
93	        combination: { weights: { ...rankFusionWeights } },
94	        input: {
95	          pipelines: {
96	            lexical: [
97	              {
98	                $search: {
99	                  compound: {
100	                    filter: lexicalFilter,
101	                    must: [
102	                      {
103	                        text: {
104	                          fuzzy: { maxEdits: 1 },
105	                          // Both analyzer paths: the German multi for
106	                          // compound stemming and umlaut folding, the
107	                          // default for code-switched English.
108	                          path: ["text", { multi: "german", value: "text" }],
109	                          query,
110	                        },
111	                      },
112	                    ],
113	                  },
114	                  index: FACTS_SEARCH_INDEX_NAME,
115	                },
116	              },
117	              ...lifecycle,
118	              { $limit: perArm },
119	            ],
120	            semantic: [
121	              {
122	                $vectorSearch: {
123	                  filter: vectorFilter,
124	                  index: FACTS_VECTOR_INDEX_NAME,
125	                  limit: perArm,
126	                  numCandidates: limit * NUM_CANDIDATES_MULTIPLIER,
127	                  path: "text",
128	                  // Automated Embedding takes the query as text and embeds
129	                  // it server-side with the index's model.
130	                  query: { text: query },
131	                },
132	              },
133	              ...lifecycle,
134	            ],
135	          },
136	        },
137	        scoreDetails: true,
138	      },
139	    },
140	    { $limit: limit },
141	  ];
142	};
143	
144	export interface RetrievedFact {
145	  fact: Fact;
146	  /** Present only when a reranker ran. */
147	  relevanceScore?: number;
148	}
149	
150	export interface RetrieveFactsOptions extends HybridFactsSearchOptions {
151	  /**
152	   * Optional cross-encoder pass over the fused candidates. Omitted, results
153	   * come back in fusion order — useful for a cheap path, and the only option
154	   * until a rerank key is configured.
155	   */
156	  rerank?: (
157	    query: string,
158	    documents: Fact[]
159	  ) => Promise<RerankedDocument<Fact>[]>;
160	}
161	
162	/**
163	 * The callable read path: fuse the two arms in the database, then optionally
164	 * rerank. Needs Atlas — `$search` and `$vectorSearch` run on mongot, which a
165	 * plain mongod does not have, so this composition is verified against a live
166	 * cluster rather than in the local test suite.
167	 */
168	export const retrieveFacts = async (
169	  db: Db,
170	  { rerank, ...search }: RetrieveFactsOptions
171	): Promise<RetrievedFact[]> => {
172	  const { facts } = getCollections(db);
173	  const fused = await facts
174	    .aggregate<Fact>(buildHybridFactsPipeline(search))
175	    .toArray();
176	
177	  if (!rerank || fused.length === 0) {
178	    return fused.map((fact) => ({ fact }));
179	  }
180	  const ranked = await rerank(search.query, fused);
181	  return ranked.map(({ document, relevanceScore }) => ({
182	    fact: document,
183	    relevanceScore,
184	  }));
185	};
186	
187	export interface RerankableDocument {
188	  text: string;
189	}
190	
191	export interface RerankedDocument<T extends RerankableDocument> {
192	  document: T;
193	  relevanceScore: number;
194	}
195	
196	export interface VoyageRerankConfig {
197	  apiKey?: string;
198	  baseUrl?: string;
199	  /** Injectable for tests; only ever called as (url, init). */
200	  fetchImpl?: (url: string, init: RequestInit) => Promise<Response>;
201	  model?: string;
202	  /** Documents handed to the cross-encoder. Beyond this the tail is dropped. */
203	  topK?: number;
204	}
205	
206	const DEFAULT_RERANK_BASE_URL = "https://api.voyageai.com/v1";
207	// The lite model is the interactive default: the quality gap on short
208	// candidates is small and this sits on the latency-sensitive path.
209	const DEFAULT_RERANK_MODEL = "rerank-2.5-lite";
210	const DEFAULT_TOP_K = 50;
211	
212	/**
213	 * Cross-encoder reranking over the fused candidate set.
214	 *
215	 * Deliberately the API rather than the `$rerank` aggregation stage: a stage is
216	 * bound to one collection, whereas this takes an arbitrary list and can
217	 * therefore rank facts and raw source excerpts against each other — which
218	 * matters, because a facts-only read path measurably loses recall.
219	 *
220	 * Errors propagate. A reranker that silently falls back to fusion order turns
221	 * a broken dependency into a quiet quality regression.
222	 */
223	export const createVoyageRerank = <T extends RerankableDocument>(
224	  config: VoyageRerankConfig = {}
225	): ((query: string, documents: T[]) => Promise<RerankedDocument<T>[]>) => {
226	  const apiKey = config.apiKey ?? process.env.VOYAGE_API_KEY;
227	  if (!apiKey) {
228	    throw new Error(
229	      "VOYAGE_API_KEY is required (pass config.apiKey or set the env var)"
230	    );
231	  }
232	  const baseUrl = config.baseUrl ?? DEFAULT_RERANK_BASE_URL;
233	  const doFetch = config.fetchImpl ?? fetch;
234	  const model = config.model ?? DEFAULT_RERANK_MODEL;
235	  const topK = config.topK ?? DEFAULT_TOP_K;
236	
237	  return async (query, documents) => {
238	    if (documents.length === 0) {
239	      return [];
240	    }
241	    const candidates = documents.slice(0, topK);
242	    const res = await doFetch(`${baseUrl}/rerank`, {
243	      body: JSON.stringify({
244	        documents: candidates.map((candidate) => candidate.text),
245	        model,
246	        query,
247	      }),
248	      headers: {
249	        authorization: `Bearer ${apiKey}`,
250	        "content-type": "application/json",
251	      },
252	      method: "POST",
253	    });
254	    if (!res.ok) {
255	      const body = await res.text();
256	      throw new Error(`rerank ${res.status}: ${body.slice(0, 500)}`);
257	    }
258	    const data = (await res.json()) as {
259	      data?: { index: number; relevance_score: number }[];
260	    };
261	
262	    const ranked: RerankedDocument<T>[] = [];
263	    for (const entry of data.data ?? []) {
264	      const document = candidates[entry.index];
265	      // The service echoes positions from the list it was sent; a position
266	      // outside it means the response does not describe this request, and
267	      // emitting undefined downstream would be worse than dropping it.
268	      if (document) {
269	        ranked.push({ document, relevanceScore: entry.relevance_score });
270	      }
271	    }
272	    return ranked;
273	  };
274	};
