import {
  createVoyageRerank,
  type Fact,
  factCategoryValues,
  retrieveFacts,
} from "@repo/knowledge";
import { getKnowledgeDb } from "@repo/knowledge/client";
import { defineTool } from "eve/tools";
import { z } from "zod";

// Built once, not per call, and only when a key is configured — without one
// the read path still works, it just returns fusion order instead of
// cross-encoder order.
let rerank: ReturnType<typeof createVoyageRerank<Fact>> | null | undefined;
const getRerank = () => {
  if (rerank === undefined) {
    rerank = process.env.VOYAGE_API_KEY ? createVoyageRerank<Fact>() : null;
  }
  return rerank ?? undefined;
};

export default defineTool({
  description:
    "Search the company knowledge base for confirmed facts about people, organizations and engagements. Call this before answering any question about who someone is, what a client wants, or what was decided — you have no knowledge of this company otherwise. Returns each fact with the id you must cite it by.",
  async execute(input, ctx) {
    // The tenant comes from the verified session, never from the model. A
    // tenantId in the tool input would be attacker-reachable through prompt
    // injection in any ingested email.
    const tenantId = ctx.session.auth.current?.attributes?.tenantId;
    if (typeof tenantId !== "string" || tenantId.length === 0) {
      throw new Error(
        "No active organization on this session; cannot search the knowledge base."
      );
    }

    const results = await retrieveFacts(getKnowledgeDb(), {
      category: input.category,
      query: input.query,
      rerank: getRerank(),
      tenantId,
    });

    return {
      // Shaped for citation: the id is the thing the model has to reproduce
      // exactly, so it leads. Dates and ObjectIds are stringified because tool
      // output crosses a durable JSON boundary.
      facts: results.map(({ fact, relevanceScore }) => ({
        category: fact.category,
        confidence: fact.confidence,
        id: fact._id.toHexString(),
        relevanceScore,
        text: fact.text,
        validFrom: fact.validFrom?.toISOString() ?? null,
      })),
      searched: input.query,
    };
  },
  inputSchema: z.object({
    category: z
      .enum(factCategoryValues)
      .optional()
      .describe(
        "Narrow to one kind of fact. Omit unless the question is clearly about only one — narrowing costs recall."
      ),
    query: z
      .string()
      .min(1)
      .describe(
        "What to look for, in the language the facts are likely written in. A name, a topic, or a short phrase works better than a full sentence."
      ),
  }),
});

import { z } from "zod";
import { baseDocFields } from "./shared";

export const sourceStatusValues = [
  "received",
  "transcribing",
  "transcribed",
  "extracting",
  "proposed",
  "reviewed",
  "failed",
] as const;

export const sourceSchema = z.object({
  ...baseDocFields,
  attachments: z
    .array(
      z.object({
        blobUrl: z.url(),
        contentType: z.string().min(1),
        filename: z.string().min(1),
      })
    )
    .optional(),
  audio: z
    .object({
      blobUrl: z.url(),
      contentType: z.string().min(1),
      durationSeconds: z.number().positive().optional(),
    })
    .optional(),
  // Set by the erasure cascade when every fact backed by this source is gone:
  // the caller must delete the referenced blobs, then unset audio/attachments.
  blobsPendingDeletion: z.boolean().optional(),
  capturedBy: z.string().min(1),
  // The textual payload: transcript (voice), body (email), or pasted text (manual).
  content: z.string().optional(),
  email: z
    .object({
      forwardedBy: z.string().min(1),
      messageId: z.string().min(1),
      originalSender: z.string().min(1),
      sentAt: z.date(),
      subject: z.string(),
    })
    .optional(),
  error: z.string().optional(),
  // Failure budget for the extraction worker: consecutive failed attempts.
  // At the worker's maxAttempts the status flips to "failed" instead of
  // retrying forever; a successful run clears it.
  extractionAttempts: z.number().int().min(0).optional(),
  // When the described events actually happened, as distinct from createdAt
  // (when we captured them). An email carries its own sentAt; a forwarded
  // thread can describe something far older than the moment it reached us.
  // Facts extracted from this source inherit it as their validFrom.
  occurredAt: z.date().optional(),
  status: z.enum(sourceStatusValues),
  // Same failure-budget convention as extractionAttempts, for the
  // transcription stage.
  transcriptionAttempts: z.number().int().min(0).optional(),
  type: z.enum(["voice", "email", "manual"]),
});
export type Source = z.infer<typeof sourceSchema>;

