  ...baseDocFields,
  endDate: z.date().optional(),
  organizationId: zodObjectId,
  startDate: z.date().optional(),
  status: z.enum(engagementStatusValues),
  title: z.string().min(1),
  type: z.string().min(1),
});
export type Engagement = z.infer<typeof engagementSchema>;

