import { ObjectId } from "mongodb";

/** Fixture id namespaces. Kept apart so an org id can never collide with a fact id. */
export const ID_KIND = {
  organization: 0xa1,
  person: 0xa2,
  engagement: 0xa3,
  source: 0xa4,
